import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;

public class MessageQueueConsumer {

    private final BlockingQueue<Message> queue;
    private final CircuitBreaker circuitBreaker;
    private final ExecutorService executor;
    private final MessagePool messagePool;
    private volatile boolean running = true;

    public MessageQueueConsumer(int poolSize, int threshold, long resetTimeout) {
        this.queue = new LinkedBlockingQueue<>(1000);
        this.circuitBreaker = new CircuitBreaker(threshold, resetTimeout);
        this.executor = Executors.newFixedThreadPool(4);
        this.messagePool = new MessagePool(poolSize);
    }

    public void submit(String payload) {
        Message msg = messagePool.acquire();
        msg.setPayload(payload);
        msg.setTimestamp(System.nanoTime());
        queue.offer(msg);
    }

    public void startConsumers(Consumer<String> handler) {
        for (int i = 0; i < 4; i++) {
            executor.submit(() -> consumeLoop(handler));
        }
    }

    private void consumeLoop(Consumer<String> handler) {
        while (running) {
            try {
                Message msg = queue.poll(100, TimeUnit.MILLISECONDS);
                if (msg == null) continue;

                if (circuitBreaker.isOpen()) {
                    // Circuit is open - schedule for retry after half-open check
                    scheduleRetry(msg, handler);
                    continue;
                }

                processMessage(msg, handler);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void processMessage(Message msg, Consumer<String> handler) {
        try {
            handler.accept(msg.getPayload());
            circuitBreaker.recordSuccess();
        } catch (Exception e) {
            circuitBreaker.recordFailure();
            if (circuitBreaker.isOpen()) {
                scheduleRetry(msg, handler);
                return;
            }
        } finally {
            // Return message to pool for reuse only if not scheduled for retry
            if (msg.getRetainCount() == 0) {
                messagePool.release(msg);
            }
        }
    }

    private void scheduleRetry(Message msg, Consumer<String> handler) {
        msg.retain();
        String payloadSnapshot = msg.getPayload();
        CompletableFuture.delayedExecutor(
            circuitBreaker.getResetTimeout(), TimeUnit.MILLISECONDS
        ).execute(() -> {
            try {
                if (circuitBreaker.attemptHalfOpen()) {
                    handler.accept(payloadSnapshot);
                    circuitBreaker.recordSuccess();
                } else {
                    // Create fresh message for re-enqueue
                    Message fresh = messagePool.acquire();
                    fresh.setPayload(payloadSnapshot);
                    fresh.setTimestamp(System.nanoTime());
                    queue.offer(fresh);
                }
            } finally {
                msg.releaseRetain();
                if (msg.getRetainCount() == 0) {
                    messagePool.release(msg);
                }
            }
        });
    }

    public void shutdown() {
        running = false;
        executor.shutdownNow();
    }

    static class Message {
        private volatile String payload;
        private volatile long timestamp;
        private final AtomicBoolean inUse = new AtomicBoolean(false);
        private final AtomicInteger retainCount = new AtomicInteger(0);

        void setPayload(String payload) { this.payload = payload; }
        String getPayload() { return this.payload; }
        void setTimestamp(long ts) { this.timestamp = ts; }
        long getTimestamp() { return this.timestamp; }
        boolean acquire() { return inUse.compareAndSet(false, true); }
        void release() { this.payload = null; inUse.set(false); }
        void retain() { retainCount.incrementAndGet(); }
        void releaseRetain() { retainCount.decrementAndGet(); }
        int getRetainCount() { return retainCount.get(); }
    }

    static class MessagePool {
        private final BlockingQueue<Message> pool;

        MessagePool(int size) {
            pool = new LinkedBlockingQueue<>(size);
            for (int i = 0; i < size; i++) {
                pool.offer(new Message());
            }
        }

        Message acquire() {
            Message msg = pool.poll();
            if (msg == null) {
                msg = new Message();
            }
            msg.acquire();
            return msg;
        }

        void release(Message msg) {
            msg.release();
            pool.offer(msg);
        }
    }

    static class CircuitBreaker {
        private final int failureThreshold;
        private final long resetTimeout;
        private final AtomicInteger failureCount = new AtomicInteger(0);
        private final AtomicInteger successCount = new AtomicInteger(0);
        private volatile long lastFailureTime = 0;
        private final AtomicReference<State> state = new AtomicReference<>(State.CLOSED);

        enum State { CLOSED, OPEN, HALF_OPEN }

        CircuitBreaker(int threshold, long resetTimeout) {
            this.failureThreshold = threshold;
            this.resetTimeout = resetTimeout;
        }

        boolean isOpen() {
            if (state.get() == State.OPEN) {
                if (System.currentTimeMillis() - lastFailureTime >= resetTimeout) {
                    return false; // Allow half-open attempt
                }
                return true;
            }
            return false;
        }

        boolean attemptHalfOpen() {
            return state.compareAndSet(State.OPEN, State.HALF_OPEN);
        }

        void recordSuccess() {
            successCount.incrementAndGet();
            failureCount.set(0);
            state.set(State.CLOSED);
        }

        void recordFailure() {
            lastFailureTime = System.currentTimeMillis();
            if (failureCount.incrementAndGet() >= failureThreshold) {
                state.set(State.OPEN);
            }
        }

        long getResetTimeout() { return resetTimeout; }
    }
}
